@st.cache_data(show_spinner="깊이마다 모델을 새로 학습하는 중…")   # 한 번 계산한 결과는 다시 쓴다
def rf_depth_sweep():
    rows = []
    for d in [1, 2, 3, 4, 5, 6, 7, 8, 10, 12, 15, 20]:
        forest = RandomForestClassifier(max_depth=d, class_weight="balanced", random_state=42).fit(X_train, y_train)
        p = forest.predict(X_test)
        rows.append({"깊이": d, "학습용 F1": f1_score(y_train, forest.predict(X_train)),
                     "시험용 F1": f1_score(y_test, p, zero_division=0),
                     "찾은 환자(시험용)": int(((p == 1) & (y_test == 1)).sum())})
    return pd.DataFrame(rows).round(3)

sweep = rf_depth_sweep()
st.plotly_chart(px.line(sweep, x="깊이", y=["학습용 F1", "시험용 F1"], markers=True))
st.dataframe(sweep, hide_index=True)
